import{useState}from'react';import{Alert,Pressable,StyleSheet,Text,View}from'@/platform/react-native';import{useLocalSearchParams,router}from'@/router';import{useMutation,useQuery,useQueryClient}from'@tanstack/react-query';import{api}from'@/lib/api';import{Badge,Button,Card,EmptyState,Header,Input,Muted,Screen,SectionTitle,useAppTheme}from'@/components/UI';
export default function Governance(){const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const[list,setList]=useState(true);const[title,setTitle]=useState('');const[body,setBody]=useState('');const q=useQuery<any[]>({queryKey:['governance',id],queryFn:async()=>(await api.get(`/communities/${id}/governance/proposals`)).data});const create=useMutation({mutationFn:()=>api.post(`/communities/${id}/governance/proposals`,{title,body}),onSuccess:()=>{setTitle('');setBody('');setList(true);qc.invalidateQueries({queryKey:['governance',id]})}});return <Screen scroll><Header title="Community Governance" subtitle="Proposal → discussion → amendments → voting → decision → action" right={<Button title={list?'New':'List'} variant="secondary" onPress={()=>setList(!list)}/>}/>{list?<>{!q.data?.length?<EmptyState title="No proposals yet" body="Members can bring structured proposals into a transparent decision process."/>:q.data.map((p:any)=><Pressable key={p.Id} onPress={()=>router.push(`/community/${id}/proposal/${p.Id}` as any)}><Card><View style={s.top}><Text style={[s.title,{color:palette.text}]}>{p.Title}</Text><Badge text={p.Status}/></View><Muted>{p.Summary||p.Body}</Muted><View style={s.meta}><Muted>{p.DiscussionCount} discussions</Muted><Muted>{p.AmendmentCount} amendments</Muted></View></Card></Pressable>)}<Button title="Search Decision Register" variant="secondary" onPress={()=>router.push(`/community/${id}/decisions` as any)}/><Button title="Formal Voting" variant="secondary" onPress={()=>router.push(`/community/${id}/formal-voting` as any)}/></>:<><SectionTitle>New proposal</SectionTitle><Input value={title} onChangeText={setTitle} placeholder="Proposal title"/><Input value={body} onChangeText={setBody} placeholder="Explain the proposal, reason and expected outcome" multiline/><Button title="Publish for discussion" loading={create.isPending} onPress={()=>title.trim()&&body.trim()?create.mutate():Alert.alert('Missing details')}/></>}</Screen>};const s=StyleSheet.create({top:{flexDirection:'row',justifyContent:'space-between',gap:10},title:{fontWeight:'900',fontSize:16,flex:1},meta:{flexDirection:'row',gap:16,marginTop:10}})
